Set<int> fn0(String ciphertext, String plaintext) {
  final result = <int>{};
  final n = ciphertext.length;
  if (n == 0 || n != plaintext.length) {
    return result;
  }
  for (var k = 0; k < 26; k++) {
    final bad = <int>[];
    for (var i = 0; i < n; i++) {
      final p = plaintext.codeUnitAt(i) - 97;
      final c = ciphertext.codeUnitAt(i) - 97;
      if ((p + k) % 26 != c) {
        bad.add(i);
        if (bad.length > 2) {
          break;
        }
      }
    }
    if (bad.length > 2) {
      continue;
    }
    if (bad.isEmpty || bad.length == 1) {
      result.add(k);
      continue;
    }
    final i = bad[0];
    final j = bad[1];
    if (j == i + 1) {
      final pI = plaintext.codeUnitAt(i) - 97;
      final pJ = plaintext.codeUnitAt(j) - 97;
      final cI = ciphertext.codeUnitAt(i) - 97;
      final cJ = ciphertext.codeUnitAt(j) - 97;
      if ((pJ + k) % 26 == cI && (pI + k) % 26 == cJ) {
        result.add(k);
      }
    }
  }
  return result;
}

