List<int> fn0(List<int> phaseMasks, int cycleBits) {
  if (cycleBits <= 0 || cycleBits > 30) {
    return <int>[];
  }

  final int limitMask = (1 << cycleBits) - 1;
  final List<int> result = <int>[];

  int rotateLeft(int value, int shift) {
    shift %= cycleBits;
    value &= limitMask;
    return ((value << shift) | (value >> (cycleBits - shift))) & limitMask;
  }

  int leadingGreenRun(int value) {
    int run = 0;
    while (run < cycleBits && ((value >> run) & 1) == 1) {
      run++;
    }
    return run;
  }

  int transitionCount(int value) {
    int count = 0;
    for (int i = 0; i < cycleBits; i++) {
      int current = (value >> i) & 1;
      int next = (value >> ((i + 1) % cycleBits)) & 1;
      if (current != next) {
        count++;
      }
    }
    return count;
  }

  for (final int rawMask in phaseMasks) {
    final int mask = rawMask & limitMask;
    int best = mask;
    int bestRun = -1;
    int bestTransitions = cycleBits + 1;

    for (int shift = 0; shift < cycleBits; shift++) {
      final int rotated = rotateLeft(mask, shift);
      final int run = leadingGreenRun(rotated);
      final int transitions = transitionCount(rotated);

      if (run > bestRun ||
          (run == bestRun && transitions < bestTransitions) ||
          (run == bestRun &&
              transitions == bestTransitions &&
              rotated < best)) {
        best = rotated;
        bestRun = run;
        bestTransitions = transitions;
      }
    }

    result.add(best);
  }

  return result;
}

