      runs.add(currentRank);
      runs.add(runCount);
      runs.add(suitSum);
      currentRank = card.rank;
      runCount = 1;
      suitSum = card.suit;
    }
  }
  runs.add(currentRank);
  runs.add(runCount);
  runs.add(suitSum);

