Set<int> fn0(List<List<int>> cycles, int minSharedArea) {
  final List<List<int>> rects = <List<int>>[];
  final List<int> xs = <int>[];
  final List<int> ys = <int>[];
  for (final cycle in cycles) {
    if (cycle.length < 5) continue;
    int x1 = cycle[1], y1 = cycle[2], x2 = cycle[3], y2 = cycle[4];
    if (x1 > x2) { final t = x1; x1 = x2; x2 = t; }
    if (y1 > y2) { final t = y1; y1 = y2; y2 = t; }
    if (x1 == x2 || y1 == y2) continue;
    rects.add(<int>[cycle[0], x1, y1, x2, y2]);
    if (!xs.contains(x1)) xs.add(x1);
    if (!xs.contains(x2)) xs.add(x2);
    if (!ys.contains(y1)) ys.add(y1);
    if (!ys.contains(y2)) ys.add(y2);
  }
  if (rects.isEmpty) return <int>{};
  xs.sort();
  ys.sort();
  final Map<int, int> sharedArea = <int, int>{};
  for (int xi = 0; xi + 1 < xs.length; xi++) {
    final int left = xs[xi], right = xs[xi + 1];
    for (int yi = 0; yi + 1 < ys.length; yi++) {
      final int bottom = ys[yi], top = ys[yi + 1];
      final List<int> covering = <int>[];
      for (final r in rects) {
        if (r[1] <= left && right <= r[3] && r[2] <= bottom && top <= r[4]) {
          covering.add(r[0]);
        }
      }
      if (covering.length > 1) {
        final int area = (right - left) * (top - bottom);
        for (final id in covering) {
          sharedArea[id] = (sharedArea[id] ?? 0) + area;
        }
      }
    }
  }
  final Set<int> result = <int>{};
  for (final r in rects) {
    if ((sharedArea[r[0]] ?? 0) >= minSharedArea) result.add(r[0]);
  }
  return result;
}

